export const DATA_86: ReadingTest[] = [
  { id: "rd-134", num: 134, title: "Đề 134", timeMin: 60, parts: [
    { title: "A Model with a Free Spirit", paragraphs: ["I still remember the first time I saw a photograph of Lena Ardway in a fashion magazine. She was not wearing a tight designer dress like the other models. Instead, she wore a loose cotton skirt covered in flowers, a beaded necklace, and sandals made of leather. From that moment, I became a fan of her work, not only because of her beauty, but because of the relaxed, natural style she brought to every photo shoot.", "Lena grew up in a small town near the coast, where her parents ran a little shop that sold handmade jewelry and clothes. As a child, she often helped her mother choose colorful fabrics and mix different patterns together. This early experience shaped the way she later presented herself to the world. When she became a professional model at the age of twenty, she refused to follow the strict rules of the fashion industry. She told one interviewer that she wanted her photos to feel like \"a walk through a sunny field,\" not like a formal business meeting.", "Soon, Lena's hippie style became famous across the fashion world. Magazines began asking her to wear flowing dresses, round sunglasses, and flowers in her hair. Many young people copied her look because it felt easy and comfortable, unlike some other trends that required expensive clothes. Lena once said in a magazine article that fashion should make a person feel free, not trapped. Her fans loved this honest message, and her popularity grew quickly during those years.", "Despite her success, Lena never changed her simple lifestyle. She still lived in a small wooden house near the beach and spent her free time painting or playing guitar with friends. Photographers who worked with her often said that she brought a calm , peaceful energy to every shoot, which made the final pictures look more natural than the work of other models. People who attended her photo sessions noticed that she always asked the team to use natural light instead of bright studio lamps, because she believed real sunlight made the pictures feel warmer and more honest.", "Today, Lena Ardway is remembered not just for her unique hippie style, but for showing the fashion industry that beauty does not need to be perfect or expensive. Many younger models now mention her as an inspiration, saying that her relaxed attitude changed the way people think about modeling. For me, she will always be the model who taught everyone that being comfortable in your own skin is more important than following every new trend."], questions: [{ q: "What is the main idea of the passage?", options: ["Fashion magazines asked Lena to wear flowing dresses and round sunglasses", "Lena Ardway grew up near a beach with her parents' shop", "Lena Ardway's relaxed, natural style made her a memorable and influential model", "Photographers preferred using natural light during Lena's photo sessions"], answer: 2 }, { q: "According to the passage, where did Lena Ardway grow up?", options: ["In a town famous for handmade jewelry shops", "In a wooden house far from the sea", "In a big city known for fashion shows", "In a small town near the coast"], answer: 3 }, { q: "Why did Lena ask photographers to use natural light during shoots?", options: ["She found natural light easier for the team to set up", "She thought studio lamps were too expensive to use", "She wanted the photos to look like business meetings", "She believed it made the pictures feel warmer and more honest"], answer: 3 }, { q: "At what point in her life did Lena become a professional model?", options: ["When she was a teenager helping in her parents' shop", "When she first appeared in a magazine photograph", "Shortly after she moved to a wooden house by the beach", "At the age of twenty"], answer: 3 }, { q: "The word \"famous\" in paragraph 3 is closest in meaning to _______.", options: ["old-fashioned", "expensive", "well-known", "complicated"], answer: 2 }, { q: "The word \"calm\" in paragraph 4 is closest in meaning to _______.", options: ["formal", "exciting", "peaceful", "uncertain"], answer: 2 }, { q: "The word \"her\" in paragraph 4 refers to _______.", options: ["the photographers", "Lena Ardway", "the other models", "the fashion magazines"], answer: 1 }, { q: "According to the passage, which of the following is NOT mentioned as part of Lena's style?", options: ["Tall leather boots", "Flowing dresses", "Round sunglasses", "Flowers in her hair"], answer: 0 }, { q: "According to the passage, what message did Lena share in a magazine article?", options: ["Expensive clothes are necessary to look beautiful", "Models should avoid wearing colorful patterns", "Fashion should always follow strict industry rules", "Fashion should make a person feel free, not trapped"], answer: 3 }, { q: "What can be inferred by connecting information from paragraph 2 and paragraph 5?", options: ["Lena's childhood experience with fabrics shaped a style that later inspired younger models", "Younger models copied Lena only because of her sunglasses", "Lena stopped enjoying fashion after becoming successful", "Lena's parents disagreed with her choice to become a model"], answer: 0 }] },
    { title: "Understanding Left-Handedness", paragraphs: ["Roughly ten percent of the world's population is left-handed, a trait that has puzzled scientists for generations. Although left-handed individuals have existed throughout recorded history, the reasons behind this preference remain only partially understood. Researchers generally agree that handedness is influenced by a combination of genetic factors and brain development, although no single gene has been identified as the sole cause. Instead, current evidence suggests that dozens of genes may each contribute a small effect, working together with environmental influences during early childhood.", "For centuries, left-handed people faced significant social pressure to change their natural tendency. In many cultures, the left hand was associated with negative qualities, while the right hand was linked to skill and trustworthiness. As a result, parents and teachers often forced left-handed children to write and eat with their right hand instead. This practice, once common in schools across several countries, sometimes caused confusion in young children, occasionally leading to stuttering or difficulty concentrating, since the brain's natural wiring was being forcibly altered.", "Modern science has changed this view considerably. Researchers studying brain activity have found that left-handed individuals often show a less rigid pattern of language processing, meaning that language functions may be distributed across both hemispheres of the brain rather than concentrated mainly on one side, as is typical in right-handed people. Some scientists believe this flexible wiring could be connected to creative thinking, although the evidence on this point remains debated, with several studies producing inconsistent results.", "Interestingly, certain professions appear to attract a higher-than-average proportion of left-handed individuals. Architecture, music composition, and competitive fencing are frequently cited examples. These fields may benefit from spatial or strategic advantages that some researchers associate with left-hand dominance, though critics argue that such claims are often based on limited sample sizes rather than rigorous large-scale studies. It is worth noting that correlation does not necessarily indicate causation, and further research is needed before firm conclusions can be drawn.", "Daily life still presents practical challenges for left-handed people. Everyday tools, from scissors to kitchen can openers, are typically designed with right-handed users in mind, forcing left-handed individuals to adapt or seek specially designed alternatives. Even something as simple as writing can be awkward, since the hand tends to smudge ink while moving across the page from left to right. Manufacturers have gradually responded to this demand, producing left-handed versions of certain products, though the selection remains noticeably smaller than that available for right-handed consumers.", "Despite these obstacles, attitudes toward left-handedness have shifted dramatically over the past few decades. Schools no longer attempt to forcibly retrain left-handed students, and many parents now view the trait simply as a natural variation rather than something requiring correction. Public figures across sports, politics, and the arts have openly embraced their left-handedness, helping to normalize what was once viewed with suspicion. This cultural shift reflects a broader trend in which scientific understanding gradually replaces outdated social assumptions.", "Looking ahead, researchers hope that continued study of handedness will shed light on broader questions about brain development and individual variation. Some scientists speculate that understanding why left-handedness persists at a stable rate across populations, despite the practical disadvantages it can present, might reveal deeper truths about how genetic diversity is maintained within a species over long periods of time."], questions: [{ q: "What is the main idea of the passage?", options: ["Left-handed people are naturally more creative than right-handed people", "Left-handedness involves complex causes, past social pressure, and ongoing practical challenges", "Left-handedness is caused entirely by a single inherited gene", "Left-handed people have always been treated equally throughout history"], answer: 1 }, { q: "According to the passage, approximately what proportion of people are left-handed?", options: ["Fifty percent", "Five percent", "Ten percent", "Twenty percent"], answer: 2 }, { q: "According to the passage, what sometimes happened when children were forced to switch hands?", options: ["They were excused from schoolwork entirely", "They developed stronger right-hand coordination permanently", "They became more skilled at writing than right-handed peers", "They occasionally experienced stuttering or difficulty concentrating"], answer: 3 }, { q: "Which professions does the passage mention as having a higher proportion of left-handed individuals?", options: ["Medicine, law, and teaching", "Architecture, music composition, and competitive fencing", "Journalism, accounting, and engineering", "Cooking, farming, and carpentry"], answer: 1 }, { q: "The word \"suggests\" in paragraph 1 is closest in meaning to _______.", options: ["proves conclusively", "denies", "indicates", "questions"], answer: 2 }, { q: "The word \"rigorous\" in paragraph 4 is closest in meaning to _______.", options: ["thorough", "biased", "outdated", "informal"], answer: 0 }, { q: "The word \"These\" in paragraph 4 refers to _______.", options: ["the named professions", "research studies", "brain hemispheres", "left-handed children"], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a practical challenge for left-handed people?", options: ["Difficulty finding left-handed kitchen tools", "Scissors designed for right-handed use", "Ink smudging while writing", "Trouble reading printed text"], answer: 3 }, { q: "According to the passage, how does language processing often differ in left-handed individuals?", options: ["It may be distributed across both hemispheres rather than mainly one side", "It is completely absent in one hemisphere", "It develops slower than in right-handed people", "It relies exclusively on the right hemisphere"], answer: 0 }, { q: "What can be inferred by connecting information from paragraph 6 and paragraph 7?", options: ["Public figures avoid mentioning their left-handedness due to lingering stigma", "Schools still actively try to convert left-handed students today", "Scientists have already fully explained why left-handedness persists across generations", "Continued research into handedness may help explain broader patterns of genetic diversity, reflecting a shift from past social suspicion to scientific curiosity"], answer: 3 }] },
    { title: "Urban Rail Networks Across Southeast Asia", paragraphs: ["Over the past two decades, several Southeast Asian capitals have invested heavily in urban rail systems, hoping to ease chronic congestion while reshaping how millions of residents move through sprawling metropolitan areas. [1] Bangkok, Kuala Lumpur, and Singapore each followed markedly different trajectories in developing their metro networks, shaped by distinct political structures, funding mechanisms, and historical patterns of urban growth. Comparing these three systems reveals not merely differences in track length or ridership figures, but contrasting philosophies about how public infrastructure should be financed, governed, and integrated into daily urban life.", "Singapore's Mass Rapid Transit, inaugurated in 1987, is frequently held up as a regional benchmark , largely because its development was inseparable from the city-state's broader land-use planning. [2] Rather than retrofitting rail lines into an already congested city, planners incorporated the MRT into Singapore's master plan decades before construction began, allowing residential towns to be built directly around future stations. This sequencing, planning first and building second, meant that ridership grew organically as new towns matured, rather than struggling to attract passengers to a network grafted onto pre-existing sprawl. Critics, however, note that this top-down approach was only feasible because of the government's near-total control over land allocation, a condition not easily replicated elsewhere in the region.", "Bangkok's experience diverged considerably. [3] The city's first elevated train line, the BTS Skytrain, did not open until 1999, more than a decade after Singapore's system, and its expansion has been shaped by a patchwork of competing operators, overlapping concession contracts, and periodic disputes over fare integration. Unlike Singapore's centrally coordinated approach, Bangkok's network evolved through a combination of private concessions and state-backed extensions, resulting in a system where commuters sometimes must purchase separate tickets to transfer between lines operated by different companies. This fragmentation has drawn criticism from urban planners, who argue that the absence of a single unified fare card has discouraged some residents from abandoning private vehicles altogether, even as the rail network itself has expanded substantially in route coverage.", "Kuala Lumpur presents something of a middle case. [4] Its rail network, comprising several lines built across different decades under different administrations, has historically suffered from a lack of coordinated planning, with light rail, monorail, and commuter rail systems initially operating with minimal physical or fare integration. In recent years, however, a series of reforms, including the introduction of a unified contactless payment system and the construction of interchange stations connecting previously disconnected lines, has narrowed the gap between Kuala Lumpur's network and its more tightly coordinated neighbors. Transport officials have suggested that these improvements reflect a broader recognition that fragmented systems impose hidden costs on commuters, even when individual lines themselves are well constructed and reliable.", "Funding structures further distinguish the three systems. Singapore's MRT has relied heavily on direct government investment, allowing fares to remain comparatively low without the network falling into financial distress, since infrastructure costs are substantially absorbed by the state rather than recovered solely through ticket revenue. Bangkok's system, by contrast, has depended more heavily on private capital and build-operate-transfer arrangements, a structure that accelerated initial construction but has also meant that fare levels are more directly tied to the commercial interests of individual concessionaires. Kuala Lumpur occupies an intermediate position, with government-linked companies playing a substantial role while still incorporating elements of private participation in specific line extensions.", "Ridership patterns also reflect these structural differences. Singapore consistently records among the highest per-capita metro usage rates in the region, a fact often attributed not only to network density but to complementary policies, such as steep vehicle ownership taxes, that make private car ownership prohibitively expensive for many residents. Bangkok's ridership, while substantial in absolute terms given the city's enormous population, remains proportionally lower, a pattern some economists link to the continued affordability of motorcycle taxis as a flexible alternative for short trips that the rail network does not always serve efficiently. Kuala Lumpur's ridership has grown steadily as integration improves, though sprawling suburban development patterns continue to limit the network's reach into lower-density residential areas.", "Looking forward, all three cities face the challenge of extending rail coverage into peripheral areas where population growth is fastest, yet where construction costs per passenger served are often highest. Whether each government continues prioritizing centralized planning, private partnership, or incremental integration will likely determine not just how quickly these networks expand, but whether they manage to draw enough commuters away from private vehicles to meaningfully ease the congestion that originally motivated their construction."], questions: [{ q: "What is the main idea of the passage?", options: ["Kuala Lumpur's rail network has remained completely fragmented despite recent efforts", "Singapore's MRT is objectively superior to all other Southeast Asian metro systems", "Bangkok's BTS Skytrain has failed to attract sufficient ridership since opening", "The three cities' metro systems reflect distinct planning philosophies and funding approaches shaped by their political and historical contexts"], answer: 3 }, { q: "According to the passage, what distinguished the sequencing of Singapore's MRT development from Bangkok's?", options: ["Bangkok planned its network decades in advance, while Singapore built its system reactively", "Both cities followed identical planning sequences but differed only in opening dates", "Singapore built stations before residential towns existed around them, while Bangkok's line was added after urban sprawl had already formed", "Singapore relied on private concessions while Bangkok used only government funding"], answer: 2 }, { q: "Why do commuters in Bangkok sometimes need separate tickets to transfer between lines?", options: ["Different lines are operated by different companies under separate concession contracts", "The government refuses to allow fare integration for security reasons", "The BTS Skytrain does not connect physically to other lines", "Bangkok has not yet built any underground rail infrastructure"], answer: 0 }, { q: "According to the passage, what recent change has helped narrow the gap between Kuala Lumpur and its neighbors?", options: ["Complete privatization of all rail lines", "A unified contactless payment system and new interchange stations", "The elimination of light rail in favor of monorail only", "A government ban on private vehicle ownership"], answer: 1 }, { q: "The word \"benchmark\" in paragraph 2 is closest in meaning to _______.", options: ["anomaly", "standard", "burden", "obstacle"], answer: 1 }, { q: "The word \"fragmentation\" in paragraph 3 is closest in meaning to _______.", options: ["affordability", "efficiency", "disconnection", "expansion"], answer: 2 }, { q: "The word \"these\" in paragraph 4 refers to _______.", options: ["monorail systems", "different administrations", "decades of construction", "the recent reforms"], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a feature of the three cities' funding structures?", options: ["Bangkok's use of build-operate-transfer arrangements", "Singapore's reliance on direct government investment", "Kuala Lumpur's intermediate position involving government-linked companies", "Singapore offering free fares for all elderly residents"], answer: 3 }, { q: "What can be inferred from paragraphs 2 and 6 about why Singapore has high per-capita metro usage?", options: ["Motorcycle taxis are banned entirely in Singapore", "Singapore's coordinated planning combined with policies that make car ownership expensive jointly encourage rail usage", "Singapore has more total track length than any other city in the world", "Singapore's MRT charges no fares whatsoever"], answer: 1 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'Yet despite sharing this common motivation, none of the three networks emerged from identical circumstances.'", options: ["[2]", "[1]", "[4]", "[3]"], answer: 1 }] },
    { title: "The Evolutionary Trajectory of Monetary Systems", paragraphs: ["The historical progression of money, from tangible commodities to representative certificates to today's fiat currencies, constitutes far more than a sequence of technical substitutions. [1] Each transition reflects a deeper renegotiation of trust, one in which societies gradually shifted the basis of monetary confidence away from intrinsic physical value and toward institutional credibility, a shift whose implications continue to shape contemporary debates over currency stability and central bank authority.", "Commodity money, the earliest form, derived its value from the inherent usefulness or scarcity of the underlying material itself, whether gold, salt, or cattle, meaning that the medium of exchange and the store of value were, in effect, one and the same physical object. This self-referential quality offered a particular kind of stability: [2] a gold coin retained worth regardless of who issued it or which government collapsed, precisely because its value was not contingent upon any institutional guarantee. Yet this same property imposed severe practical constraints, as the supply of precious metals could not expand in step with growing economic activity, and the physical weight of commodities rendered large-scale transactions cumbersome at best.", "Representative money emerged as a partial solution to these logistical burdens, introducing paper certificates that derived their legitimacy not from any value inherent in the paper itself, but from a contractual promise of redemption, typically for a fixed quantity of gold or silver held in reserve. [3] This innovation did not abandon the underlying logic of commodity backing; rather, it abstracted that logic one layer further, substituting physical possession with a claim upon possession, thereby allowing trade to proceed at a velocity and scale that bullion alone could never have sustained. Crucially, however, this system's stability remained contingent upon a verifiable link between paper in circulation and metal in reserve, a link that proved increasingly difficult to maintain as governments faced fiscal pressures, particularly during periods of war, when the temptation to issue certificates beyond available reserves grew acute.", "The eventual move toward fiat currency, money whose value derives not from any commodity backing but from legal decree and public confidence in the issuing authority, did not occur as a single decisive break but unfolded gradually across the twentieth century, accelerating markedly after the 1971 suspension of dollar convertibility into gold. [4] What makes fiat currency conceptually distinct is not merely the absence of physical backing, but the explicit relocation of monetary trust from a tangible object to an abstract institutional apparatus, namely, central banks tasked with managing money supply in pursuit of price stability and economic growth.", "This relocation of trust carries profound implications that are not always immediately apparent. Whereas commodity money's value was, in principle, insulated from any single institution's mismanagement, fiat money's value is inextricably bound to the perceived competence and independence of the issuing central bank. Episodes of hyperinflation, from interwar Germany to more recent cases in Latin America, illustrate what occurs when public confidence in this institutional apparatus collapses: the currency's purchasing power can evaporate not because the paper itself has changed, but because the underlying trust that gave it meaning has been withdrawn.", "Some economists argue that fiat money's apparent vulnerability is, paradoxically, also its greatest strength, since the absence of a fixed commodity anchor grants central banks the flexibility to expand or contract money supply in response to economic conditions, a flexibility that commodity-backed systems structurally preclude . Critics counter that this very flexibility introduces a persistent temptation toward monetary indiscipline, one that historical commodity standards, whatever their practical limitations, were specifically designed to forestall. This tension between flexibility and discipline remains unresolved, animating ongoing debates about whether contemporary monetary frameworks strike an appropriate balance.", "What this trajectory ultimately reveals is that money has never been a purely technical instrument but rather a social technology whose functioning depends upon collective belief, a belief that has migrated, over centuries, from the tangible reassurance of metal in hand to an increasingly abstract confidence in institutions whose mandates few citizens fully understand yet upon whose stewardship modern economic life nonetheless depends."], questions: [{ q: "What is the main idea of the passage?", options: ["Central banks were created specifically to replace gold as a form of currency", "The evolution from commodity to representative to fiat money reflects a gradual shift in the basis of monetary trust from physical value to institutional credibility", "Hyperinflation only occurs in countries that abandon commodity-backed currency", "Fiat currency is inherently less stable than commodity money in all circumstances"], answer: 1 }, { q: "According to the passage, why did commodity money offer a particular kind of stability?", options: ["Its value was not contingent upon any institutional guarantee, since it derived from the material itself", "Its value depended on government guarantees that rarely failed", "It was lightweight and convenient for large transactions", "Its supply expanded easily alongside economic growth"], answer: 0 }, { q: "According to the passage, what made representative money's stability difficult to maintain?", options: ["Governments sometimes issued certificates beyond their available reserves, especially during wartime", "The paper certificates had no contractual basis at all", "Gold and silver became entirely worthless during this period", "Citizens refused to accept paper certificates as legitimate currency"], answer: 0 }, { q: "According to the passage, what event is associated with accelerating the shift toward fiat currency?", options: ["The founding of the first central bank in history", "The discovery of new gold reserves in the twentieth century", "The 1971 suspension of dollar convertibility into gold", "The introduction of the first paper certificates"], answer: 2 }, { q: "The word \"contingent\" in paragraph 2 is closest in meaning to _______.", options: ["dependent", "permanent", "abundant", "irrelevant"], answer: 0 }, { q: "The word \"preclude\" in paragraph 6 is closest in meaning to _______.", options: ["measure", "delay", "encourage", "rule out"], answer: 3 }, { q: "The word \"that\" in paragraph 3 refers to _______.", options: ["the paper certificates", "the fiscal pressures", "the gold mines", "the link between circulation and reserves"], answer: 3 }, { q: "According to the passage, which of the following is NOT mentioned as a characteristic or limitation of commodity money?", options: ["It was cumbersome to transport for large transactions", "Its supply could not expand easily with economic growth", "Its value did not depend on any issuing institution", "It could be instantly converted into digital records"], answer: 3 }, { q: "What can be inferred by connecting information from paragraphs 4 and 5 about fiat currency?", options: ["Its value depends on institutional trust, making it vulnerable to collapse if confidence in central banks is lost", "Its value is permanently fixed by international treaties", "It cannot be affected by central bank mismanagement", "It was designed primarily to eliminate the need for central banks"], answer: 0 }, { q: "Which of the following square brackets [1] , [2] , [3] , or [4] best indicates where the following sentence could be added? 'This independence from institutional backing made commodity money uniquely resistant to political upheaval.'", options: ["[2]", "[3]", "[1]", "[4]"], answer: 0 }] },
  ] },
  { id: "rd-185", num: 185, title: "Đề 185", timeMin: 60, parts: [
    { title: "Why We Read and Write About Remarkable Lives", paragraphs: ["Across many classrooms, students spend hours learning about the lives of remarkable people, and this simple activity offers more value than it might first appear. Teachers often select three kinds of figures for study — a scientist, an inventor, and a social reformer — because each one teaches a different lesson. Marie Curie, the physicist who discovered radioactivity, is a common choice, as are inventors like Thomas Edison and reformers like the environmentalist Wangari Maathai. When students read about these lives and then write short accounts of them, they gain skills and habits of mind that reach well beyond a single history lesson.", "Reading about Marie Curie, for example, shows students what steady effort can accomplish. She worked for years in a small, poorly equipped laboratory before her research on radioactivity earned her two Nobel Prizes, one in physics and one in chemistry. Students who read this story rarely forget the lesson that big discoveries usually come from long, patient work rather than sudden luck. Beyond the facts themselves, following a life story from childhood to old age also helps young readers practice a skill they need for almost every subject: identifying cause and effect across a long stretch of time.", "Writing about a figure such as Thomas Edison brings a different kind of benefit. To produce even a short biography, a student must gather facts from several sources, decide which details matter most, and put events in a clear order — skills that are useful in almost any piece of writing, not just history reports. Edison's own life, marked by thousands of failed experiments before his team perfected the light bulb, also gives young writers practical material for building an argument: they must explain not just what happened, but why persistence eventually led to success.", "A third benefit appears when the subject is a reformer like Wangari Maathai, who organized the planting of millions of trees to fight poverty and soil loss in Kenya. Because her story involves real communities facing real hardship, students reading and writing about her work often develop a stronger sense of empathy than they would from a textbook chapter alone. Some teachers report that after completing such projects, students become noticeably more interested in local environmental problems, though this shift in attitude is harder to measure than a simple gain in vocabulary or reading speed.", "Taken together, these three kinds of stories — the scientist's patience, the inventor's persistence, and the reformer's compassion — give students something that facts alone cannot: a set of models for how a person might respond to difficulty. For this reason, many literacy programs now pair a reading unit with a short writing assignment on the same person, so that the two activities reinforce each other rather than standing apart. Whether the goal is stronger vocabulary, clearer organization in writing, or a broader understanding of the world, biography remains a surprisingly efficient classroom tool."], questions: [{ q: "According to the passage, what did Marie Curie eventually receive after years of work in a poorly equipped laboratory?", options: ["Two Nobel Prizes, one in chemistry and one in medicine", "A single lifetime achievement award for science work", "One Nobel Prize, awarded only in physics research", "Two Nobel Prizes, one in physics and one in chemistry"], answer: 3 }, { q: "What is the main idea of the passage?", options: ["Marie Curie's discovery of radioactivity was the passage's central subject", "Writing about inventors matters more than reading about scientists or reformers", "Any biography assignment automatically raises students' test scores in school", "Studying such lives builds both skills and helpful attitudes in students"], answer: 3 }, { q: "The word \"persistence\" in paragraph 3 is closest in meaning to _______.", options: ["stubbornness", "persuasion", "determination", "curiosity"], answer: 2 }, { q: "What does the passage say happened before Edison's team perfected the light bulb?", options: ["Thousands of investors withdrew their financial support", "A single experiment failed before quick success followed", "Thousands of experiments failed during the process", "Several competitors released similar inventions first"], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a benefit of reading and writing about remarkable lives?", options: ["Learning to organize facts in a clear written order", "Developing stronger empathy for people facing real hardship", "Practicing how to identify cause and effect over time", "Improving the ability to memorize exact historical dates"], answer: 3 }, { q: "The word \"her\" (in \"her story,\" paragraph 4) refers to _______.", options: ["a social reformer", "Marie Curie", "Wangari Maathai", "real communities"], answer: 2 }, { q: "What did Wangari Maathai organize in Kenya, according to the passage?", options: ["The building of new community schools", "The planting of thousands of trees", "A nationwide literacy campaign for children", "The planting of millions of trees"], answer: 3 }, { q: "The word \"compassion\" in paragraph 5 is closest in meaning to _______.", options: ["tolerance", "sympathy", "curiosity", "compromise"], answer: 1 }, { q: "What can be inferred from the passage about why teachers combine reading and writing assignments on the same person?", options: ["They found that biography units raise average history exam scores", "They believe the two activities strengthen each other more than alone", "They think reading alone builds the same skills that writing does", "They believe writing assignments cause students to read less carefully"], answer: 1 }, { q: "What is the author's overall attitude toward using biographies of scientists, inventors, and reformers in the classroom?", options: ["Neutral, simply listing facts about three historical figures without opinion", "Enthusiastic, insisting biography study should replace all other assignments", "Strongly critical of relying on individual life stories in class", "Cautiously favorable, presenting biography as an efficient teaching tool"], answer: 3 }] },
    { title: "Rethinking the Causes of Urban Homelessness", paragraphs: ["For decades, the public conversation about homelessness has often centered on individual failings — addiction, mental illness, or poor personal choices. This framing offers a simple story: people are homeless because they made mistakes. Yet a growing body of research complicates this account substantially, suggesting that in many major cities the primary driver of rising homelessness is not personal misfortune at all, but something far more structural : the widening gap between wages and the cost of housing.", "Cities with the tightest housing markets, researchers have found, consistently report the highest rates of homelessness, regardless of how generous or limited their social services happen to be. Two cities may offer nearly identical support programs, yet the one where rents have risen fastest will almost always show more people sleeping outside. This pattern does not mean addiction and mental illness play no role in individual cases; rather, it suggests that when housing becomes scarce enough, even a relatively minor personal setback — a missed paycheck, a sudden medical bill — can be enough to push someone onto the street.", "Some economists argue that a housing shortage, rather than being an unavoidable side effect of urban growth, is often the product of specific local decisions — zoning laws that restrict new construction, lengthy permit processes, and neighborhood opposition to denser housing. Whether these policies were designed deliberately to limit supply is debated, but their practical effect, several studies suggest, has been to slow construction well below the pace needed to keep up with population growth, pushing prices upward for years at a stretch.", "None of this is meant to dismiss the real struggles that many homeless individuals face. Rates of untreated mental illness and substance dependency among the homeless population remain far higher than in the general public, and outreach workers consistently describe these conditions as major daily obstacles to finding stable housing. What the newer research challenges is not the existence of these problems but the assumption that they are the root cause for most people who become homeless, rather than a consequence that often develops or worsens after someone loses stable shelter.", "A widely cited approach known as Housing First reverses the traditional order of intervention: instead of requiring sobriety or treatment completion before offering an apartment, case workers place a person in stable housing immediately and then connect them with support services. Several long-term studies tracking this model report that a majority of participants remain housed after two years, and that many go on to seek treatment voluntarily once their living situation has stabilized — a result that surprised early critics who had expected housing without conditions to fail.", "Critics of Housing First point out that the model is expensive to scale in cities where land and construction costs are already extremely high, and that its early results came mostly from mid-sized cities rather than the largest, most expensive metropolitan areas. Whether the same outcomes would hold in a city with a far more severe housing shortage — of the kind described earlier — remains an open question that current data cannot fully answer.", "Taken together, these findings do not offer a single tidy explanation for homelessness, nor a guaranteed solution. They do, however, suggest that policies focused narrowly on individual behavior are unlikely to substantially reduce homelessness in cities where housing costs continue to outpace wages. Any lasting response, most researchers now agree, will need to address the underlying shortage of affordable housing alongside, not instead of, the mental health and addiction services that many homeless individuals still clearly need."], questions: [{ q: "According to the passage, what has research found about cities with the tightest housing markets?", options: ["They show homelessness rates similar to cities with generous services", "They show that they consistently report the highest rates of homelessness", "They show high homelessness only when social services are limited", "They show lower homelessness than cities with looser housing markets"], answer: 1 }, { q: "The word \"structural\" in paragraph 1 is closest in meaning to _______.", options: ["accidental", "temporary", "systemic", "architectural"], answer: 2 }, { q: "What is the main idea of the passage?", options: ["The Housing First program has fully solved homelessness in most cities", "Housing costs, more than personal failings, largely drive urban homelessness", "Homelessness rates are now declining across most major world cities", "Addiction and mental illness are the true root causes of homelessness"], answer: 1 }, { q: "What do some economists argue causes housing shortages in many cities?", options: ["Zoning laws designed mainly to protect historic buildings", "Neighborhood opposition to lowering property tax rates", "Local decisions such as zoning laws and slow permit processes", "A sudden nationwide drop in construction worker availability"], answer: 2 }, { q: "According to the passage, which of the following is NOT mentioned as a barrier homeless individuals face?", options: ["A sudden medical bill or a missed paycheck", "Untreated mental illness or substance dependency", "Limited access to public transportation in the city", "The high cost of scaling programs like Housing First"], answer: 2 }, { q: "The word \"their\" (in \"their practical effect,\" paragraph 3) refers to _______.", options: ["population growth rates", "several studies", "these local policies", "urban economists"], answer: 2 }, { q: "What does the passage suggest about the limitations of the Housing First model?", options: ["Its early success may not apply to major expensive cities", "It has never succeeded in keeping any participants housed long-term", "It has been rejected by every city that has tried it", "It works only in cities with no zoning restrictions at all"], answer: 0 }, { q: "The word \"voluntarily\" in paragraph 5 is closest in meaning to _______.", options: ["occasionally", "willingly", "reluctantly", "financially"], answer: 1 }, { q: "What can be inferred from the passage about the relationship between housing stability and mental health treatment?", options: ["Gaining stable housing may make some people more willing to pursue treatment", "Outreach workers believe treatment access has improved in most cities recently", "Mental health treatment is required before anyone can receive stable housing", "Stable housing eliminates the need for any mental health treatment"], answer: 0 }, { q: "What is the author's overall purpose in this passage?", options: ["To prove that Housing First is the only effective solution available", "To argue that mental health services should be eliminated from homelessness policy", "To criticize city governments for failing to build enough housing", "To highlight structural housing costs in homelessness policy"], answer: 3 }] },
    { title: "When Founders Choose Blood Over Merit: The Murch Family Business", paragraphs: ["Family business succession has long attracted attention from management scholars, in part because so many well-known cautionary tales involve founders who assumed that fairness meant equal treatment. The case of Elias Murch, who built a mid-sized manufacturing firm from a single workshop into a regional employer over four decades, is frequently cited in this literature. When Murch died, he left the company not to whichever child had proven most capable of running it, but in four equal shares, one to each of his four children, regardless of how involved each of them had actually been in the business.", "Subsequent research on family firms has generally found that equal division of ownership among heirs, however intuitively fair it may seem to a departing founder, destabilizes governance more often than distribution weighted by involvement or demonstrated competence. The Murch case illustrates this pattern with unusual clarity. On paper, each of the four Murch children held an identical twenty-five percent stake and, in principle, an identical voice in company decisions; in practice, only one sibling had spent any meaningful time inside the business before their father's death.", "While Elias Murch appears to have believed that equal shares would prevent resentment among his children and preserve family harmony, the eldest daughter, Margaret, had worked in operations for over a decade and understood the firm's finances, suppliers, and staff far better than her three siblings, none of whom held any operating role at the time of the inheritance. This mismatch between formal ownership and informal expertise, rather than the inheritance itself, is what family-business researchers now consider the more decisive factor in what followed.", "Within two years, disagreements over whether profits should be paid out as dividends or reinvested in new equipment produced a series of voting deadlocks, since no single sibling's twenty-five percent stake could outweigh a coalition of the others, and no coalition proved stable for long. Margaret, who wanted to expand production capacity, found herself repeatedly outvoted by siblings who preferred immediate payouts, even though two of them privately admitted, according to later interviews, that they knew little about the operational trade-offs involved. The company eventually required an outside mediator simply to approve a routine equipment purchase.", "Some family-business scholars suggest that formal succession plans, drafted and agreed upon before a founder's death, tend to reduce this kind of conflict, since they can allocate voting rights or management authority according to role rather than birth order or sentiment alone. The available evidence, however, is mixed: firms with written succession plans do appear to experience fewer immediate governance disputes, but the effect seems to depend heavily on how much the plan itself was discussed openly among heirs beforehand, rather than simply drafted in private by the founder.", "A newer strand of research complicates this picture further, arguing that the quality of sibling relationships established well before succession, not the formal governance structure adopted afterward, may be the stronger predictor of how a family firm fares once ownership changes hands. By this account, a written plan can formalize cooperation that already exists, but it cannot manufacture cooperation where longstanding rivalry or emotional distance already divides the heirs — a possibility the Murch case, where the siblings had reportedly grown apart in adulthood, does little to rule out.", "None of this proves that equal inheritance alone caused the Murch company's later difficulties, since the siblings' strained relationship and the mismatch between ownership and expertise were already in place well before Elias Murch's death. What the case does suggest, and what later researchers have used it to illustrate, is that an ownership structure designed to look fair on paper can still produce governance that functions poorly in practice, particularly when it ignores differences in who actually understands how the business runs."], questions: [{ q: "According to the passage, how did Elias Murch divide ownership of his company among his children?", options: ["He split it into four equal shares regardless of their involvement", "He gave the largest share to the child who had worked in the business", "He divided it unequally based on each child's age at his death", "He placed the entire company under a single trustee for all four"], answer: 0 }, { q: "The word \"mismatch\" in paragraph 3 is closest in meaning to _______.", options: ["delay", "mixture", "misunderstanding", "discrepancy"], answer: 3 }, { q: "What is the main idea of the passage?", options: ["Equal inheritance can create governance problems when it ignores differences in expertise", "Family businesses always fail once a founder divides ownership equally", "Elias Murch intentionally favored his eldest daughter over his other children", "Written succession plans guarantee harmony among siblings after a founder's death"], answer: 0 }, { q: "What caused repeated voting deadlocks in the company?", options: ["No single sibling's share could outvote a stable coalition of the others", "An outside mediator blocked all decisions until a new plan was signed", "Three siblings sold their shares to outside investors within two years", "Margaret refused to allow any sibling to vote on financial matters"], answer: 0 }, { q: "According to the passage, which of the following is NOT mentioned as a factor relevant to how the Murch company fared after succession?", options: ["How openly the succession plan was discussed among heirs beforehand", "The exact amount of profit paid out as dividends each year", "The quality of the siblings' personal relationships before succession", "The mismatch between ownership shares and business expertise"], answer: 1 }, { q: "The word \"their\" (in \"before their father's death,\" paragraph 2) refers to _______.", options: ["the business itself", "the four Murch children", "the company's board", "one sibling"], answer: 1 }, { q: "The word \"manufacture\" (in \"cannot manufacture cooperation,\" paragraph 6) is closest in meaning to _______.", options: ["assemble", "repair", "package", "produce"], answer: 3 }, { q: "What can be inferred from the passage about the role of Elias Murch's decision to divide ownership equally?", options: ["The siblings' strained relationship caused Murch to divide ownership equally in the first place", "Margaret would have inherited the entire company had a formal plan existed", "The equal division was the only cause of the deadlocks that followed his death", "It contributed to later difficulties but was not the sole cause"], answer: 3 }, { q: "What is the author's purpose in presenting the Murch case within the passage?", options: ["To argue that family businesses should never be inherited by more than one heir", "To show governance issues caused by equal inheritance", "To criticize Elias Murch personally for favoring one child over the others", "To summarize the complete history of the Murch manufacturing company"], answer: 1 }, { q: "According to the passage, what distinguished Margaret from her three siblings at the time of their father's death?", options: ["She had extensive operational experience and business knowledge", "She was the only sibling who had signed a formal succession plan", "She was the youngest of the four children and newest to the firm", "She was the only sibling who wanted immediate dividend payouts"], answer: 0 }] },
    { title: "The Productivity Paradox Revisited: Why New Technology Does Not Always Raise Output", paragraphs: ["Despite several decades of rapid advances in computing, communication, and, more recently, artificial intelligence, aggregate productivity growth across most advanced economies has, if anything, slowed rather than accelerated — a pattern economists have labeled the productivity paradox. Not only does this trend contradict the intuitive assumption that more powerful tools should make workers more efficient, but it has also persisted, with only brief interruptions, across several waves of technological change that each promised, at the time, to be the exception.", "One explanation, favored by some economists, holds that productivity statistics simply fail to capture the real gains new technology delivers, since much of what digital tools produce — convenience, personalization, faster communication — does not show up cleanly in output measures designed for an industrial economy. This measurement-gap argument may account for part of the discrepancy, though it does not necessarily explain why the slowdown appears most pronounced in sectors, such as retail and administrative services, where digital adoption has been most extensive and where output should, in principle, be easiest to measure.", "A second, less measurement-focused explanation suggests that while individual firms often do become more efficient after adopting new technology, these firm-level gains do not automatically aggregate into economy-wide productivity growth, because resources — capital, skilled labor, management attention — are frequently absorbed by a small number of highly digitized firms at the expense of the many firms that adopt more slowly or not at all. Under this account, technology may be reallocating advantage rather than expanding total output, a distinction that conventional productivity statistics are not well equipped to detect.", "A third strand of research, arguably the most cautious in its claims, argues that the benefits of any general-purpose technology tend to arrive only after firms have substantially reorganized how work is done around it, a process that historically has taken a decade or more even for transformative innovations such as electrification. If artificial intelligence follows a similar trajectory, current productivity data may simply be too early to reflect its eventual effects — though this argument, critics note, has also been used, with decreasing plausibility each time, to explain away every technology slowdown of the past forty years.", "Skeptics of the reorganization-lag argument point out that it is, by its very nature, difficult to falsify : any failure of a new technology to raise productivity within a given period can always be attributed to organizational adjustment still being underway, regardless of how long that period has already lasted. This does not mean the argument is wrong, only that it should be weighed against explanations that make more falsifiable, near-term predictions, such as the measurement-gap and reallocation hypotheses discussed above, whose implications can at least in principle be tested against sector-specific data available today.", "None of these three explanations is, on current evidence, sufficient on its own to resolve the paradox, and most researchers now treat them as complementary rather than competing: measurement almost certainly understates some genuine gains, resource reallocation likely explains part of the growing gap between leading and lagging firms, and organizational adjustment probably does delay at least some of the benefits of newly adopted tools, even if that delay cannot excuse every instance of stagnant growth indefinitely.", "What the debate does suggest, cautiously, is that the relationship between technological capability and measured economic output is far less direct than popular narratives about innovation often assume, and that policies built on the expectation of near-term productivity gains from any single new technology, artificial intelligence included, may be resting on a historical record that offers, at best, mixed and delayed support for that expectation."], questions: [{ q: "What is the main idea of the passage?", options: ["Artificial intelligence has already reversed the long-standing productivity paradox", "Resource reallocation alone fully explains the persistent productivity slowdown", "Productivity statistics are completely incapable of measuring any technological gains", "Slowing productivity growth likely stems from several complementary, uncertain factors"], answer: 3 }, { q: "What does the measurement-gap explanation fail to fully account for?", options: ["Why the slowdown was directly caused by the introduction of productivity statistics", "Why the slowdown is most pronounced in heavily digitized sectors", "Why the slowdown is guaranteed to occur in every digitized sector without exception", "Why the slowdown never occurs in heavily digitized sectors at all"], answer: 1 }, { q: "The word \"falsify\" in paragraph 5 is closest in meaning to _______.", options: ["postpone", "forge", "exaggerate", "disprove"], answer: 3 }, { q: "What does the reorganization-lag explanation claim about general-purpose technologies?", options: ["Their benefits appear immediately, before any organizational change occurs", "Their benefits are guaranteed to appear within exactly ten years of adoption", "Their benefits appear only after work is reorganized around them", "Their benefits never appear unless a firm replaces its entire workforce"], answer: 2 }, { q: "According to the passage, which of the following is NOT presented as a possible explanation for the productivity paradox?", options: ["Resources being absorbed by a small number of highly digitized firms", "A decline in the overall quality of newly hired workers", "Firms needing time to reorganize work around new technology", "Productivity statistics failing to capture real technological gains"], answer: 1 }, { q: "The phrase \"the argument\" (paragraph 5) refers to _______.", options: ["the reorganization-lag explanation described in paragraph 4", "the measurement-gap explanation described in paragraph 2", "the skeptics' criticism described in paragraph 5 itself", "the reallocation explanation described in paragraph 3"], answer: 0 }, { q: "What can be inferred from the passage about how most researchers currently view the three explanations for the productivity paradox?", options: ["They have concluded that productivity statistics need no further improvement", "They believe the three explanations contradict each other and cannot coexist", "They likely see the explanations as complementary, not competing", "They are certain that organizational reorganization lag is the single true cause"], answer: 2 }, { q: "The word \"stagnant\" in paragraph 6 is closest in meaning to _______.", options: ["accelerating", "declining", "unchanging", "seasonal"], answer: 2 }, { q: "What is the author's overall attitude toward claims that a single explanation resolves the productivity paradox?", options: ["Dismissive of all three explanations as equally implausible", "Cautiously skeptical, favoring a combination of partial, uncertain explanations", "Fully convinced that the reorganization-lag argument is correct", "Neutral, simply listing explanations without evaluating their plausibility"], answer: 1 }, { q: "According to the passage, what weakness do skeptics identify in the reorganization-lag explanation?", options: ["It is difficult to falsify because delays can always be blamed on adjustment", "It was already disproven by sector-specific productivity data decades ago", "It has never once been proposed by any economist studying productivity", "It applies only to artificial intelligence and no other historical technology"], answer: 0 }] },
  ] },
];
